 case WM_DRAWITEM:{auto*d=(DRAWITEMSTRUCT*)lp;int idx=(int)d->CtlID-ID_DASH;if(idx>=0&&idx<4){HBRUSH b=CreateSolidBrush((int)page==idx?RGB(0,70,91):panel);FillRect(d->hDC,&d->rcItem,b);DeleteObject(b);SetBkMode(d->hDC,TRANSPARENT);SetTextColor(d->hDC,(int)page==idx?RGB(100,230,255):RGB(190,205,218));const wchar_t*t[]={L"Обзор",L"Внешний вид",L"Поведение",L"О программе"};DrawTextW(d->hDC,t[idx],-1,&d->rcItem,DT_CENTER|DT_VCENTER|DT_SINGLELINE);return TRUE;}break;}
 case WM_COMMAND:{int id=LOWORD(wp);if(id>=ID_DASH&&id<=ID_ABOUT){ShowPage((Page)(id-ID_DASH));InvalidateRect(h,nullptr,TRUE);return 0;}if(id==ID_HUD_TOGGLE){ToggleHud();return 0;}if(id==ID_APPLY){if(page==APPEARANCE){cfg.opacity=(int)SendMessageW(controls[11],TBM_GETPOS,0,0);cfg.width=(int)SendMessageW(controls[13],TBM_GETPOS,0,0);cfg.height=(int)SendMessageW(controls[15],TBM_GETPOS,0,0);cfg.position=(int)SendMessageW(controls[17],CB_GETCURSEL,0,0);}if(page==BEHAVIOR){int ids[]={19,20,21,22,23};bool*v[]={&cfg.animations,&cfg.mouse,&cfg.reactor,&cfg.decorations,&cfg.autostart};for(int i=0;i<5;i++)*v[i]=SendMessageW(controls[ids[i]],BM_GETCHECK,0,0)==BST_CHECKED;Startup(cfg.autostart);}Save();ApplyHudOpacity();MessageBoxW(h,L"Настройки сохранены в jarvis.ini.",APP_NAME,MB_OK|MB_ICONINFORMATION);return 0;}break;}
